#!/usr/bin/env bash
# =============================================================================
#  DeepSeek Harness supervisor
#
#  GENERATED by the @local/dsh-wrainrock-daemon plugin — do not edit by hand; the
#  plugin rewrites this file whenever its configuration changes.
#
#  systemd starts this script (see ~/.config/systemd/user/dsh-wrainrock-daemon.service).
#  The script owns the crash / corruption recovery ladder:
#
#    1. preflight  validate the composed profile config before every start and
#                  restore the last known-good copy when it is corrupt
#    2. supervise  run `dsh`, measure how long it stayed up, and count rapid
#                  failures inside a rolling window
#    3. escalate   after FAIL_THRESHOLD rapid failures, boot the pristine safe
#                  profile instead, write an incident report to
#                  <autostart-home>/reports, and notify the desktop
#
#  Safe mode is sticky: it stays until it is explicitly reset (the plugin's
#  "复位并重启" action, or by deleting <state>/mode and restarting the unit).
#
#  Two guards keep the ladder from firing on an *environment* problem instead of
#  a broken profile. Real incident (2026-10-15): one account had two systemd
#  user managers (`user@1000.service` and `user@ian.service`), both started this
#  unit, the port loser saw EADDRINUSE, the ladder read that as "the profile
#  cannot boot" and switched to the sticky safe profile — which then fought for
#  the very same port forever, so the machine was stuck in safe mode.
#
#    * one supervisor per profile+port holds an flock; a second one (a duplicate
#      manager, a hand-started copy) stands by, takes over when the holder is
#      gone, and never counts the peer as a failure of its own
#    * a port already owned by another DSH of ours means "the service is already
#      up, owned by a peer": reported as kind `peer-port` and waited out, never
#      escalated. Safe mode also listens on its own port, so it can always come
#      up even while the normal profile still holds the main one.
#
#  Every DSH_WRAINROCK_DAEMON_* value below can be overridden from the environment, so
#  the whole ladder can be exercised without touching the real profile.
# =============================================================================
set -uo pipefail

# --- baked configuration -----------------------------------------------------
AUTOSTART_HOME="${DSH_WRAINROCK_DAEMON_HOME:-@@HOME_DIR@@}"
NODE_BIN="${DSH_WRAINROCK_DAEMON_NODE:-@@NODE_BIN@@}"
DSH_CLI="${DSH_WRAINROCK_DAEMON_CLI:-@@DSH_CLI@@}"
DSH_HOME_DIR="${DSH_WRAINROCK_DAEMON_DSH_HOME:-@@DSH_HOME@@}"
PROFILE="${DSH_WRAINROCK_DAEMON_PROFILE:-@@PROFILE@@}"
SAFE_PROFILE="${DSH_WRAINROCK_DAEMON_SAFE_PROFILE:-@@SAFE_PROFILE@@}"
SAFE_TEMPLATE="${DSH_WRAINROCK_DAEMON_SAFE_TEMPLATE:-@@SAFE_TEMPLATE@@}"
APP_ARGS="${DSH_WRAINROCK_DAEMON_APP_ARGS:-@@APP_ARGS@@}"
SAFE_APP_ARGS="${DSH_WRAINROCK_DAEMON_SAFE_APP_ARGS:-@@SAFE_APP_ARGS@@}"
# Baked as values of their own (never parsed back out of APP_ARGS) so the port
# guards below can never disagree with the command line actually launched.
PORT="${DSH_WRAINROCK_DAEMON_PORT:-@@PORT@@}"
SAFE_PORT="${DSH_WRAINROCK_DAEMON_SAFE_PORT:-@@SAFE_PORT@@}"
PORT_GUARD="${DSH_WRAINROCK_DAEMON_PORT_GUARD:-@@PORT_GUARD@@}"
STANDBY_POLL="${DSH_WRAINROCK_DAEMON_STANDBY_POLL:-5}"
UNIT_NAME="${DSH_WRAINROCK_DAEMON_UNIT:-@@UNIT_NAME@@}"
FAIL_WINDOW="${DSH_WRAINROCK_DAEMON_FAIL_WINDOW:-@@FAIL_WINDOW@@}"
FAIL_THRESHOLD="${DSH_WRAINROCK_DAEMON_FAIL_THRESHOLD:-@@FAIL_THRESHOLD@@}"
HEALTHY_SECONDS="${DSH_WRAINROCK_DAEMON_HEALTHY_SECONDS:-@@HEALTHY_SECONDS@@}"
MAX_BACKOFF="${DSH_WRAINROCK_DAEMON_MAX_BACKOFF:-@@MAX_BACKOFF@@}"
NOTIFY="${DSH_WRAINROCK_DAEMON_NOTIFY:-@@NOTIFY@@}"
# 1 = when a crash names one plugin (a `fatal uncaught exception` stack, or a
# known signature such as the inspector one), retry the NORMAL profile once with
# that plugin temporarily disabled instead of dropping the whole plugin set for
# safe mode. The overlay is a `--patch` file in the state dir and is removed
# again after a healthy boot — the profile files themselves are never edited.
CRASH_DISABLE="${DSH_WRAINROCK_DAEMON_CRASH_DISABLE:-@@CRASH_DISABLE@@}"
# Empty on a real host; `container` (or `podman`) inside distrobox/podman.
# Two user managers for one uid are the *normal* host+container layout, so the
# supervisor must not pester the user about it — only the genuine duplicate on a
# plain host is worth a warning.
CONTAINER="@@CONTAINER_KIND@@"

# --- test hooks (never set by the unit) --------------------------------------
EXEC_OVERRIDE="${DSH_WRAINROCK_DAEMON_EXEC:-}"
SKIP_PREFLIGHT="${DSH_WRAINROCK_DAEMON_SKIP_PREFLIGHT:-0}"
SKIP_SAFE_PROFILE="${DSH_WRAINROCK_DAEMON_SKIP_SAFE_PROFILE:-0}"

STATE_DIR="$AUTOSTART_HOME/state"
REPORT_DIR="$AUTOSTART_HOME/reports"
LOG_DIR="$AUTOSTART_HOME/logs"
BACKUP_DIR="$AUTOSTART_HOME/backup"
PROFILE_DIR="$DSH_HOME_DIR/profiles/$PROFILE"
LOG="$LOG_DIR/supervisor.log"
OUT_LOG="$LOG_DIR/dsh.out.log"
# Temporary crash-recovery state: never part of the profile.
RECOVERY_PATCH="$STATE_DIR/recovery-override.yml"
RECOVERY_STATE="$STATE_DIR/recovery.json"
CONFIG_FILES=(cordis.yml cordis.patch.yml package.json pnpm-workspace.yaml)

mkdir -p "$STATE_DIR" "$REPORT_DIR" "$LOG_DIR" "$BACKUP_DIR" 2>/dev/null || true

# --- small helpers -----------------------------------------------------------
now() { date +%s; }
stamp() { date -Is; }

log() {
  printf '%s [supervisor] %s\n' "$(stamp)" "$*" >>"$LOG" 2>/dev/null || true
}

read_state() { # file default
  local value=""
  [ -f "$1" ] && value="$(cat "$1" 2>/dev/null)"
  case "$value" in ''|*[!0-9]*) printf '%s' "$2" ;; *) printf '%s' "$value" ;; esac
}

write_state() { printf '%s' "$2" >"$1" 2>/dev/null || true; }

notify() { # urgency message
  [ "$NOTIFY" = "1" ] || return 0
  command -v notify-send >/dev/null 2>&1 || return 0
  notify-send -a "DeepSeek Harness" -u "${1:-normal}" "DeepSeek Harness" "$2" >/dev/null 2>&1 || true
}

# A sleep that still reacts to `systemctl stop` instead of holding shutdown for
# up to MAX_BACKOFF seconds.
interruptible_sleep() {
  sleep "$1" &
  local sleeper=$!
  wait "$sleeper" 2>/dev/null
  kill "$sleeper" 2>/dev/null || true
}

# Report an unusable generated command line at most once per failure window.
report_missing_runtime() {
  local marker="$STATE_DIR/runtime-missing.reported" age=999999
  [ -f "$marker" ] && age=$(( $(now) - $(read_state "$marker" 0) ))
  if [ "$age" -gt "$FAIL_WINDOW" ]; then
    write_state "$marker" "$(now)"
    write_incident "runtime-missing" "The generated command line cannot be used: node='$NODE_BIN' cli='$DSH_CLI'. Nothing was started, so this is NOT a clean shutdown. Regenerate the autostart files (POST /dsh-wrainrock-daemon/install, or reinstall the plugin) and restart $UNIT_NAME."
    notify critical "DeepSeek Harness 无法启动：node/dsh 路径失效，已写入报告，不会静默退出。"
  fi
  log "runtime unresolved: node='$NODE_BIN' cli='$DSH_CLI'; nothing started"
}

rotate_logs() {  if [ -f "$LOG" ] && [ "$(wc -l <"$LOG" 2>/dev/null || echo 0)" -gt 4000 ]; then
    tail -n 800 "$LOG" >"$LOG.rot" 2>/dev/null && mv -f "$LOG.rot" "$LOG"
  fi
  if [ -f "$OUT_LOG" ] && [ "$(wc -l <"$OUT_LOG" 2>/dev/null || echo 0)" -gt 8000 ]; then
    tail -n 2000 "$OUT_LOG" >"$OUT_LOG.rot" 2>/dev/null && mv -f "$OUT_LOG.rot" "$OUT_LOG"
  fi
  # keep the 20 newest incident reports
  ls -1t "$REPORT_DIR"/incident-*.md 2>/dev/null | tail -n +21 | while read -r old; do
    rm -f "$old"
  done
}

# --- singleton lock + peer awareness -----------------------------------------
# Two systemd *user managers* for one account (for example user@1000.service AND
# user@ian.service) both start this unit, so two supervisors race for one
# profile and one port. Whoever loses the port must not call it a profile
# failure: the service is up, it is simply owned by the peer.
LOCK_FILE="$STATE_DIR/supervisor-$PROFILE-${PORT:-0}.lock"
LOCK_OPENED=0

# Hold fd 9 for the whole process lifetime: flock(1) drops it when we exit, so a
# crashed supervisor can never leave a stale lock behind.
lock_open() {
  [ "$LOCK_OPENED" = "1" ] && return 0
  command -v flock >/dev/null 2>&1 || return 1
  exec 9>>"$LOCK_FILE" 2>/dev/null || return 1
  LOCK_OPENED=1
}

lock_try() {
  lock_open || return 0   # no flock(1) at all: behave exactly as before
  flock -n 9 2>/dev/null
}

port_busy() { # port
  local port="${1:-0}"
  [ "${port:-0}" -gt 0 ] 2>/dev/null || return 1
  if command -v ss >/dev/null 2>&1; then
    ss -ltnH "sport = :$port" 2>/dev/null | grep -q . && return 0
  fi
  (exec 3<>"/dev/tcp/127.0.0.1/$port") 2>/dev/null && return 0
  return 1
}

# PIDs of another DSH process whose command line names this port.
port_owner_pids() { # port
  local port="${1:-0}" entry pid cmd found=""
  [ "${port:-0}" -gt 0 ] 2>/dev/null || return 0
  for entry in /proc/[0-9]*; do
    pid="${entry#/proc/}"
    [ "$pid" = "$$" ] && continue
    cmd="$(tr '\0' ' ' <"/proc/$pid/cmdline" 2>/dev/null)" || continue
    case "$cmd" in
      *bin.js*"--port $port"*|*bin.js*"--port=$port"*) found="$found $pid" ;;
      *dsh*"--port $port"*|*dsh*"--port=$port"*) found="$found $pid" ;;
    esac
  done
  printf '%s' "${found# }"
}

# The strongest proof that the port is served by a healthy harness of ours: the
# peer answers this very plugin's status route (GET only, loopback only).
peer_serves_http() { # port
  command -v curl >/dev/null 2>&1 || return 1
  curl -fsS -m 2 -o /dev/null -H 'x-dsh-wrainrock-daemon: 1' \
    "http://127.0.0.1:$1/dsh-wrainrock-daemon/status" 2>/dev/null
}

peer_owns_port() { # port
  local port="${1:-0}"
  port_busy "$port" || return 1
  [ -n "$(port_owner_pids "$port")" ] && return 0
  peer_serves_http "$port" && return 0
  return 1
}

manager_sessions() {
  local uid
  uid="$(id -u 2>/dev/null || true)"
  command -v loginctl >/dev/null 2>&1 || return 1
  # `loginctl list-sessions` has no --class option (systemd 262 rejects it), so
  # the CLASS column is matched here instead.
  loginctl list-sessions --no-legend 2>/dev/null |
    awk -v uid="$uid" '$2 == uid { for (i = 1; i <= NF; i++) if ($i == "manager") { n++; break } } END { print n + 0 }'
}

# Do not spam a report on every retry: same one-per-window trick as the runtime
# fix. Note the kind: `peer-port`, never `safe-mode`.
report_peer_port() { # port
  local port="$1" marker="$STATE_DIR/peer-port.reported" age=999999 owners
  [ -f "$marker" ] && age=$(( $(now) - $(read_state "$marker" 0) ))
  owners="$(port_owner_pids "$port")"
  if [ "$age" -gt "$FAIL_WINDOW" ]; then
    write_state "$marker" "$(now)"
    write_incident "peer-port" "Port $port is already owned by another DeepSeek Harness instance of this autostart${owners:+ (pid $owners)}. That is not a failure of the '$PROFILE' profile, so this unit keeps '$PROFILE' selected and waits for the peer to exit instead of escalating to safe mode. This usually means two supervisors are running at once: two systemd user managers for one account, or a hand-started 'dsh web' that still holds the port."
    notify normal "端口 $port 已被另一个 Harness 实例占用（同伴实例）；保持 $PROFILE 并等待它退出，不会进入安全模式。"
  fi
  log "peer instance owns port $port; standing by (not counted as a profile failure)"
}

# Was the attempt that just ended killed by a peer holding the port? Only then is
# a rapid exit evidence about the *environment* rather than about the profile.
last_attempt_port_conflict() { # port
  local port="$1" attempt
  [ "${port:-0}" -gt 0 ] 2>/dev/null || return 1
  [ -f "$OUT_LOG" ] || return 1
  attempt="$(awk '/\[supervisor\] start mode=/{buf=""} {buf=buf $0 "\n"} END{printf "%s", buf}' "$OUT_LOG" 2>/dev/null)"
  case "$attempt" in
    *EADDRINUSE*"$port"*|*"address already in use"*"$port"*) ;;
    *) return 1 ;;
  esac
  [ -n "$(port_owner_pids "$port")" ] && return 0
  peer_serves_http "$port" && return 0
  return 1
}

# --- temporary crash recovery -------------------------------------------------
# A single profile plugin can crash the whole Harness on every start (the
# 2026-11-02 incident: `inspector: Host source is closed`). Disabling it is a
# workaround, but editing the profile to do so is permanent and wrong for what
# may be a one-off. So: read the plugin out of the failing attempt's own output,
# retry the normal profile once with a temporary `--patch` overlay that disables
# just that row, and drop the overlay as soon as a run stays healthy. The
# profile's own files are never touched.
last_attempt_output() {
  [ -f "$OUT_LOG" ] || return 0
  awk '/\[supervisor\] start mode=/{buf=""} {buf=buf $0 "\n"} END{printf "%s", buf}' "$OUT_LOG" 2>/dev/null
}

crash_plugin_ids() {
  local attempt ids=""
  attempt="$(last_attempt_output)"
  [ -n "$attempt" ] || return 0
  # Known signatures first: these name the profile *row* id, which is what a
  # `--patch` overlay targets.
  case "$attempt" in
    *"inspector: Host source is closed"*) ids="experimental-inspector" ;;
    *"session-inspector"*"Host source is closed"*) ids="session-inspector" ;;
  esac
  # Always add the package-derived candidates too: the crashing stack names the
  # npm package, and the row id is usually that package name with the leading
  # `dsh-` dropped (both spellings are cheap to include — a row that does not
  # exist only logs "entry not found" and is skipped).
  ids="$ids $(printf '%s' "$attempt" \
    | sed -n 's#.*@deepseek-ai/\(dsh-[a-z0-9-]*\)/lib/.*#\1#p' \
    | sed -e '/^dsh-base$/d' -e '/^dsh-web-app$/d' \
    | sed -e 's/^dsh-//' \
    | sort -u | tr '\n' ' ')"
  printf '%s' "$(printf '%s' "$ids" | tr ' ' '\n' | grep -v '^$' | sort -u | tr '\n' ' ' | sed -e 's/^ *//' -e 's/ *$//')"
}

last_attempt_summary() {
  local attempt line
  attempt="$(last_attempt_output)"
  line="$(printf '%s' "$attempt" | grep -m1 -E 'fatal|uncaught|Error:|error:' | cut -c1-240)"
  printf '%s' "${line:-exit code $last_exit after ${uptime}s}"
}

# One YAML row per plugin id. `--patch` layers are applied after the profile's
# own patch layer, so this disable wins for this boot only.
apply_crash_override() { # ids... ; reason
  local ids="$1" reason="$2" id first=1 reason_json ids_json=""
  [ -n "$ids" ] || return 1
  reason_json="$(printf '%s' "$reason" | tr -d '\n\r' | sed -e 's/\\/\\\\/g' -e 's/"/\\"/g')"
  {
    printf '# Generated by %s at %s — TEMPORARY crash-recovery overlay.\n' "$UNIT_NAME" "$(stamp)"
    printf '# Removed automatically after a healthy boot; never written into the profile.\n'
    printf '# Reason: %s\n' "$reason"
    for id in $ids; do
      printf -- '- id: %s\n  disabled: true\n' "$id"
    done
  } >"$RECOVERY_PATCH" 2>/dev/null || return 1
  for id in $ids; do
    [ "$first" = "1" ] || ids_json="$ids_json,"
    first=0
    ids_json="$ids_json\"$id\""
  done
  printf '{"at":"%s","ids":[%s],"reason":"%s","unit":"%s","temporary":true}\n' \
    "$(stamp)" "$ids_json" "$reason_json" "$UNIT_NAME" >"$RECOVERY_STATE" 2>/dev/null || true
  return 0
}

crash_override_active() { [ -s "$RECOVERY_PATCH" ]; }

clear_crash_override() { # why
  [ -s "$RECOVERY_PATCH" ] || { rm -f "$RECOVERY_STATE" 2>/dev/null; return 0; }
  rm -f "$RECOVERY_PATCH" "$RECOVERY_STATE" 2>/dev/null || true
  log "crash override removed ($1)"
  return 0
}

# --- state snapshot / restore ------------------------------------------------
snapshot_config() {
  [ -d "$PROFILE_DIR" ] || return 0
  local copied=0 file
  for file in "${CONFIG_FILES[@]}"; do
    if [ -f "$PROFILE_DIR/$file" ]; then
      cp -f "$PROFILE_DIR/$file" "$BACKUP_DIR/$file" 2>/dev/null && copied=$((copied + 1))
    fi
  done
  if [ "$copied" -gt 0 ]; then
    stamp >"$BACKUP_DIR/.snapshot-at"
    log "preflight: snapshot of $copied config file(s) refreshed"
  fi
}

restore_config() {
  local file
  for file in "${CONFIG_FILES[@]}"; do
    [ -f "$BACKUP_DIR/$file" ] || continue
    cp -f "$BACKUP_DIR/$file" "$PROFILE_DIR/$file" 2>/dev/null || true
  done
}

quarantine_config() {
  local dir="$REPORT_DIR/broken-$(date +%Y%m%d-%H%M%S)" file
  mkdir -p "$dir" 2>/dev/null || return 0
  for file in "${CONFIG_FILES[@]}"; do
    [ -f "$PROFILE_DIR/$file" ] && cp -f "$PROFILE_DIR/$file" "$dir/$file" 2>/dev/null
  done
  printf '%s' "$dir"
}

# --- reporting ---------------------------------------------------------------
# Collected once at startup: why this machine is not a plain single-manager box.
env_note=""

write_incident() { # kind message
  local kind="$1" message="$2" ts
  ts="$(stamp)"
  cat >"$STATE_DIR/incident.json" <<JSON
{"at":"$ts","kind":"$kind","mode":"$mode","failures":$failures,"failureThreshold":$FAIL_THRESHOLD,"windowSeconds":$FAIL_WINDOW,"lastExit":$last_exit,"uptimeSeconds":$uptime,"profile":"$PROFILE","safeProfile":"$SAFE_PROFILE","message":"$message"}
JSON
  {
    printf '# DeepSeek Harness incident — %s\n\n' "$ts"
    printf -- '- kind: `%s`\n' "$kind"
    printf -- '- mode: `%s`\n' "$mode"
    printf -- '- rapid failures: %s (threshold %s inside %ss)\n' "$failures" "$FAIL_THRESHOLD" "$FAIL_WINDOW"
    printf -- '- last child exit code: %s\n' "$last_exit"
    printf -- '- last run uptime: %ss (healthy means >= %ss)\n' "$uptime" "$HEALTHY_SECONDS"
    printf -- '- profile: `%s`   safe profile: `%s`\n' "$PROFILE" "$SAFE_PROFILE"
    printf -- '- report dir: `%s`\n\n' "$REPORT_DIR"
    printf '## What happened\n\n%s\n\n' "$message"
    if [ -n "$env_note" ]; then
      printf '## Environment\n\n%s\n\n' "$env_note"
    fi
    printf '## Leaving safe mode\n\n```\n'
    printf 'rm -f %s/mode %s/failures\n' "$STATE_DIR" "$STATE_DIR"
    printf 'systemctl --user restart %s\n' "$UNIT_NAME"
    printf '```\n\n'
    printf '## Supervisor log (tail)\n\n```\n'
    tail -n 40 "$LOG" 2>/dev/null
    printf '```\n\n## dsh output (tail)\n\n```\n'
    tail -n 30 "$OUT_LOG" 2>/dev/null
    printf '```\n'
  } >"$REPORT_DIR/incident-$ts.md" 2>/dev/null || true
  cp -f "$REPORT_DIR/incident-$ts.md" "$REPORT_DIR/latest.md" 2>/dev/null || true
  log "incident written: $REPORT_DIR/incident-$ts.md ($kind)"
  rotate_logs
}

# --- runtime resolution ------------------------------------------------------
# A generated unit goes stale: fnm removes versioned node directories, the dsh
# install moves, or a bad generation bakes empty paths. Launching a broken
# command line is worse than not launching at all — `node ""` finds no script,
# reads EOF on stdin and exits 0, which looks exactly like a clean shutdown.
# Repair what can be repaired; treat the rest as a failure, never as a clean stop.
resolve_runtime() {
  local repaired=0 candidate
  if [ ! -x "$NODE_BIN" ]; then
    for candidate in "$(command -v node 2>/dev/null || true)" \
      "$HOME"/.local/share/fnm/node-versions/*/installation/bin/node \
      /usr/local/bin/node /usr/bin/node; do
      if [ -n "$candidate" ] && [ -x "$candidate" ]; then
        NODE_BIN="$candidate"
        repaired=1
        break
      fi
    done
  fi
  if [ ! -f "$DSH_CLI" ]; then
    for candidate in "$(dirname "${NODE_BIN:-/nonexistent}" 2>/dev/null)/../lib/node_modules/@deepseek-ai/dsh/lib/bin.js" \
      "$HOME"/.local/share/fnm/node-versions/*/lib/node_modules/@deepseek-ai/dsh/lib/bin.js \
      "$HOME"/.local/share/fnm/node-versions/*/installation/lib/node_modules/@deepseek-ai/dsh/lib/bin.js \
      /usr/local/lib/node_modules/@deepseek-ai/dsh/lib/bin.js \
      /usr/lib/node_modules/@deepseek-ai/dsh/lib/bin.js; do
      if [ -n "$candidate" ] && [ -f "$candidate" ]; then
        DSH_CLI="$candidate"
        repaired=1
        break
      fi
    done
  fi
  [ "$repaired" = "1" ] && log "runtime repaired: node=$NODE_BIN cli=$DSH_CLI"
  [ -x "$NODE_BIN" ] && [ -f "$DSH_CLI" ]
}

# --- preflight ---------------------------------------------------------------
preflight() {
  local err="$STATE_DIR/preflight.err" started elapsed
  started="$(date +%s%3N)"
  if "$NODE_BIN" "$DSH_CLI" --profile "$PROFILE" --dump-config >/dev/null 2>"$err"; then
    elapsed=$(( $(date +%s%3N) - started ))
    log "preflight ok in ${elapsed}ms"
    [ -f "$BACKUP_DIR/cordis.patch.yml" ] || snapshot_config
    return 0
  fi

  local detail
  detail="$(tail -c 600 "$err" 2>/dev/null | tr '\n' ' ')"
  log "preflight: composed config for '$PROFILE' is invalid: $detail"

  if [ -f "$BACKUP_DIR/cordis.patch.yml" ]; then
    local quarantine
    quarantine="$(quarantine_config)"
    restore_config
    if "$NODE_BIN" "$DSH_CLI" --profile "$PROFILE" --dump-config >/dev/null 2>"$err"; then
      mode=normal
      write_incident "config-restored" "The composed profile config was invalid ('$detail'); it was restored from the last known-good snapshot. The broken copies are kept in $quarantine. Booting '$PROFILE' normally."
      notify normal "配置损坏，已从上次正常快照自动恢复并继续启动。"
      log "preflight: config restored from snapshot; continuing"
      return 0
    fi
    detail="$detail | after restore: $(tail -c 400 "$err" 2>/dev/null | tr '\n' ' ')"
  fi

  mode=safe
  write_state "$STATE_DIR/mode" safe
  write_incident "config-unrecoverable" "The composed profile config for '$PROFILE' cannot be composed and the last known-good snapshot did not fix it ('$detail'). Switching to safe mode."
  notify critical "配置无法恢复，已进入安全模式启动。"
  log "preflight: unrecoverable, entering safe mode"
  return 1
}

ensure_safe_profile() {
  [ "$SKIP_SAFE_PROFILE" = "1" ] && return 0
  local manifest="$DSH_HOME_DIR/profiles/$SAFE_PROFILE/package.json"
  [ -f "$manifest" ] && return 0
  log "safe mode: creating profile '$SAFE_PROFILE' from shipped template '$SAFE_TEMPLATE'"
  "$NODE_BIN" "$DSH_CLI" --profile "$SAFE_PROFILE" --from-default-profile "$SAFE_TEMPLATE" \
    --dump-config >/dev/null 2>"$STATE_DIR/safe-init.err" || true
  if [ -f "$manifest" ]; then
    log "safe mode: profile '$SAFE_PROFILE' ready"
    return 0
  fi
  log "safe mode: could not create '$SAFE_PROFILE': $(tail -c 300 "$STATE_DIR/safe-init.err" 2>/dev/null | tr '\n' ' ')"
  return 1
}

# --- peer stop ---------------------------------------------------------------
# An account can end up with two systemd user managers (user@1000.service AND
# user@ian.service); each one starts this unit, and `systemctl --user` reaches
# only the manager that owns the session bus. A restart issued through it then
# stops *that* instance while the other one keeps the port: the panel reports
# success and nothing restarts. A stop therefore takes every other supervisor of
# this install with it, so the restart comes back as exactly one fresh instance
# (and a plain `systemctl stop` really stops the service).
SELF="${BASH_SOURCE[0]:-$0}"

peer_pids() {
  local entry pid cmd
  for entry in /proc/[0-9]*; do
    pid="${entry#/proc/}"
    [ "$pid" = "$$" ] && continue
    [ -r "$entry/cmdline" ] || continue
    cmd="$(tr '\0' '\n' <"$entry/cmdline" 2>/dev/null | sed -n '2p')" || continue
    [ "$cmd" = "$SELF" ] && printf '%s\n' "$pid"
  done
}

peer_stop() {
  local pid n=0
  for pid in $(peer_pids); do
    kill -TERM "$pid" 2>/dev/null && n=$((n + 1)) || true
  done
  if [ "$n" -gt 0 ]; then
    log "stop: asked $n other supervisor(s) of this install to exit (duplicate user manager)"
  fi
  return 0
}

finish() {
  peer_stop
  exit 0
}

# --- main loop ---------------------------------------------------------------
uptime=0
stop=0
mode=normal
trap 'stop=1' TERM INT

read -r -a APP_ARGV <<<"$APP_ARGS"
read -r -a SAFE_APP_ARGV <<<"$SAFE_APP_ARGS"

# Only one supervisor may own this profile+port. A second one (typically the
# same unit started by a second systemd user manager) stands by here and takes
# over once the holder is gone: it must never start a second dsh on the same
# port, and it must never count the peer's port as a failure of its own.
if ! lock_try; then
  log "standby: another supervisor for profile '$PROFILE' port ${PORT:-0} holds $LOCK_FILE; waiting for it to exit"
  while [ "$stop" = "0" ]; do
    interruptible_sleep "$STANDBY_POLL"
    lock_try && break
  done
  if [ "$stop" = "1" ]; then
    log "standby: stop requested; exiting"
    finish
  fi
  log "standby: lock acquired; taking over profile '$PROFILE'"
fi

failures="$(read_state "$STATE_DIR/failures" 0)"
window_start="$(read_state "$STATE_DIR/window_start" 0)"
last_exit="$(read_state "$STATE_DIR/last_exit" 0)"
[ "$(cat "$STATE_DIR/mode" 2>/dev/null)" = "safe" ] && mode=safe
if [ "${1:-}" = "--force-safe" ]; then
  mode=safe
  log "started with --force-safe"
fi

managers="$(manager_sessions 2>/dev/null || true)"
if [ -n "$managers" ] && [ "$managers" -gt 1 ] 2>/dev/null && [ "$CONTAINER" = "" ]; then
  env_note="duplicate systemd user managers: $managers manager session(s) for uid $(id -u). Each one starts $UNIT_NAME, so they race for the same profile and port; the supervisor lock and the peer-port guard keep that from escalating to safe mode, but the duplicate manager itself is an environment problem worth fixing."
  log "WARNING: $managers systemd user managers for uid $(id -u); $UNIT_NAME is started once per manager"
  warned="$STATE_DIR/duplicate-managers.warned"
  if [ ! -f "$warned" ] || [ $(( $(now) - $(read_state "$warned" 0) )) -gt "$FAIL_WINDOW" ]; then
    write_state "$warned" "$(now)"
    notify normal "检测到 $managers 个 systemd 用户管理器（同一账号），它们会各启动一份 $UNIT_NAME；看护锁与端口同伴识别已生效，不会因此误入安全模式。"
  fi
elif [ -n "$CONTAINER" ]; then
  log "running inside $CONTAINER: multiple user managers are the normal host+container layout; unit pinned to this side"
fi

log "supervisor started (pid $$, profile=$PROFILE, mode=$mode, failures=$failures, threshold=$FAIL_THRESHOLD, window=${FAIL_WINDOW}s, healthy=${HEALTHY_SECONDS}s, lock=$LOCK_FILE)"

while :; do
  if [ "$stop" = "1" ]; then
    log "stop requested before start; exiting"
    finish
  fi

  if [ -z "$EXEC_OVERRIDE" ] && ! resolve_runtime; then
    report_missing_runtime
    interruptible_sleep "$MAX_BACKOFF"
    continue
  fi

  # A port already owned by another DSH of ours means the service is UP, not
  # that this profile is broken: report it once and wait instead of escalating.
  if [ "$PORT_GUARD" = "1" ]; then
    gate_port="$PORT"
    [ "$mode" = "safe" ] && gate_port="$SAFE_PORT"
    if [ "${gate_port:-0}" -gt 0 ] 2>/dev/null && peer_owns_port "$gate_port"; then
      report_peer_port "$gate_port"
      interruptible_sleep "$STANDBY_POLL"
      continue
    fi
  fi

  if [ "$mode" = "normal" ] && [ "$SKIP_PREFLIGHT" != "1" ]; then
    preflight || true
  fi

  start_cmd=()
  use_safe="$mode"
  if [ "$mode" = "safe" ]; then
    if ensure_safe_profile; then
      start_cmd=("$NODE_BIN" "$DSH_CLI" "$SAFE_PROFILE" "${SAFE_APP_ARGV[@]}")
      log "safe mode: booting profile '$SAFE_PROFILE'"
    else
      start_cmd=("$NODE_BIN" "$DSH_CLI" "$PROFILE" "${APP_ARGV[@]}")
      use_safe="safe-fallback"
      log "safe mode unavailable: falling back to '$PROFILE'"
      notify critical "安全模式不可用（无法创建 $SAFE_PROFILE），已回退到常规配置启动。"
    fi
  else
    if [ "$CRASH_DISABLE" = "1" ] && crash_override_active; then
      # Temporary, this boot only: the plugin named by the last crash stays
      # disabled until a run is healthy, then the overlay is removed again.
      start_cmd=("$NODE_BIN" "$DSH_CLI" "$PROFILE" --patch "$RECOVERY_PATCH" "${APP_ARGV[@]}")
      log "crash override active: starting '$PROFILE' with --patch $RECOVERY_PATCH"
    else
      start_cmd=("$NODE_BIN" "$DSH_CLI" "$PROFILE" "${APP_ARGV[@]}")
    fi
  fi

  start_ts="$(now)"
  write_state "$STATE_DIR/last_start" "$start_ts"
  printf '%s [supervisor] start mode=%s attempt_failures=%s cmd=%s\n' "$(stamp)" "$use_safe" "$failures" "${start_cmd[*]}" >>"$OUT_LOG" 2>/dev/null || true

  child=0
  if [ -n "$EXEC_OVERRIDE" ] && [ -x "$EXEC_OVERRIDE" ]; then
    # A test hook that names one executable is a path, and a path may contain a
    # space (this machine's is `/var/home/u/Distrobox/deepseek harness`): running
    # it unquoted splits the word and the stub never starts. Word-splitting is
    # kept only for command lines such as `sleep 30`.
    log "start(test hook): $EXEC_OVERRIDE"
    "$EXEC_OVERRIDE" >>"$OUT_LOG" 2>&1 &
    child=$!
  elif [ -n "$EXEC_OVERRIDE" ]; then
    log "start(test hook): $EXEC_OVERRIDE"
    # shellcheck disable=SC2086
    $EXEC_OVERRIDE >>"$OUT_LOG" 2>&1 &
    child=$!
  else
    "${start_cmd[@]}" >>"$OUT_LOG" 2>&1 &
    child=$!
  fi

  wait "$child"
  code=$?
  while [ "$stop" = "0" ] && kill -0 "$child" 2>/dev/null; do
    wait "$child"
    code=$?
  done

  if [ "$stop" = "1" ]; then
    kill -TERM "$child" 2>/dev/null || true
    wait "$child" 2>/dev/null || true
    log "supervisor stopped by signal; dsh terminated"
    finish
  fi

  uptime=$(( $(now) - start_ts ))
  last_exit="$code"
  write_state "$STATE_DIR/last_exit" "$last_exit"
  log "dsh exited code=$last_exit after ${uptime}s (mode=$use_safe)"

  # Never blame the profile for losing a port race: when a peer of ours owns the
  # port, this is an environment conflict — report it and wait it out.
  conflict_port="$PORT"
  [ "$use_safe" != "normal" ] && conflict_port="$SAFE_PORT"
  if [ "$uptime" -lt "$HEALTHY_SECONDS" ] && last_attempt_port_conflict "$conflict_port"; then
    report_peer_port "$conflict_port"
    interruptible_sleep "$STANDBY_POLL"
    continue
  fi

  if [ "$uptime" -ge "$HEALTHY_SECONDS" ]; then
    # One healthy run clears the ladder.
    if [ "$failures" != "0" ]; then
      log "healthy run: failure counter reset (was $failures)"
    fi
    failures=0
    window_start="$(now)"
    write_state "$STATE_DIR/failures" "$failures"
    write_state "$STATE_DIR/window_start" "$window_start"
    if [ "$use_safe" = "normal" ]; then
      snapshot_config
      rm -f "$STATE_DIR/incident.json" 2>/dev/null || true
      # The service is demonstrably healthy again with the temporary overlay:
      # put the plugin back, so the disable never outlives the incident.
      clear_crash_override "healthy run"
    fi
    if [ "$code" = "0" ]; then
      # A clean exit still means the service should be up: this is an autostart
      # daemon, so restart it. Only a stop signal (systemctl stop) ends the
      # supervisor — that path is handled by the trap above.
      log "dsh exited cleanly after ${uptime}s; restarting anyway (only systemctl stop ends the service)"
      interruptible_sleep 5
      continue
    fi
  else
    if [ "$code" = "0" ]; then
      # An instant exit 0 is a broken start (for example `node ""` reading EOF),
      # never a clean shutdown: keep retrying and escalate like any other failure.
      log "dsh exited 0 after only ${uptime}s: treated as a failed start, not a clean stop"
    fi

    local_now="$(now)"
    if [ "$window_start" -eq 0 ] || [ $((local_now - window_start)) -gt "$FAIL_WINDOW" ]; then
      failures=1
      window_start="$local_now"
    else
      failures=$((failures + 1))
    fi
    write_state "$STATE_DIR/failures" "$failures"
    write_state "$STATE_DIR/window_start" "$window_start"

    if [ "$mode" = "normal" ] && [ "$failures" -ge "$FAIL_THRESHOLD" ]; then
      # Before dropping the user's whole plugin set for safe mode, see whether
      # the failures name a single plugin: retry the normal profile once with
      # that plugin temporarily disabled. Only once per episode — if it still
      # fails with the plugin off, the next pass escalates as before.
      if [ "$CRASH_DISABLE" = "1" ] && ! crash_override_active; then
        crash_ids="$(crash_plugin_ids)"
        if [ -n "$crash_ids" ] && apply_crash_override "$crash_ids" "$(last_attempt_summary)"; then
          failures=0
          window_start="$(now)"
          write_state "$STATE_DIR/failures" "$failures"
          write_state "$STATE_DIR/window_start" "$window_start"
          write_incident "crash-override" "dsh failed $FAIL_THRESHOLD times within the window and the last attempt's output names '$crash_ids'. Instead of switching the whole profile to '$SAFE_PROFILE', '$PROFILE' is retried once with that plugin temporarily disabled through a '--patch' overlay ($RECOVERY_PATCH). The overlay is removed automatically after a healthy boot; the profile files are not modified."
          notify normal "启动连续失败，疑似插件 $crash_ids 导致；已仅为本次启动临时禁用，恢复正常后会自动撤销。"
          log "crash override applied: temporarily disabling [$crash_ids] and retrying '$PROFILE'"
          interruptible_sleep 2
          continue
        fi
      elif [ "$CRASH_DISABLE" = "1" ] && crash_override_active; then
        # The overlay was already in force and it did not help. Say so: the
        # crash then does not come from a profile row this supervisor can
        # switch off (an installation-level component, or several plugins at
        # once), and safe mode is the honest fallback.
        write_incident "crash-override-ineffective" "dsh kept failing with the temporary crash override in place ($(last_attempt_summary)). The crashing plugin therefore is not a profile row that a '--patch' overlay can disable — it is loaded outside the profile layer (an installation-level component). The override is removed and '$SAFE_PROFILE' is booted instead."
        log "crash override did not help; the crashing component is not a profile row"
      fi

      mode=safe
      write_state "$STATE_DIR/mode" safe
      clear_crash_override "escalated to safe mode"
      write_incident "safe-mode" "dsh failed $failures times within $((local_now - window_start))s (last exit code $last_exit after ${uptime}s). The profile '$PROFILE' cannot boot reliably, so the supervisor switched to the safe profile '$SAFE_PROFILE'."
      notify critical "连续 $failures 次启动失败，已进入安全模式。详见 $REPORT_DIR/latest.md"
      log "escalation: $failures rapid failures -> safe mode"
    fi
  fi

  if [ "$mode" = "safe" ]; then
    backoff="$MAX_BACKOFF"
  else
    backoff=$((2 ** failures))
    [ "$backoff" -gt "$MAX_BACKOFF" ] && backoff="$MAX_BACKOFF"
  fi
  [ "$backoff" -lt 2 ] && backoff=2
  log "restarting in ${backoff}s"
  interruptible_sleep "$backoff"
done
